<script setup lang="ts">
import {computed,reactive,ref,onMounted} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {api,message,notify,siteName} from '../api'
import {useAdminAccess} from '../composables/admin'
import Icon from '../components/Icon.vue'
const {isAdmin,isSuper}=useAdminAccess(),route=useRoute(),router=useRouter()
const tab=computed(()=>isAdmin.value&&['registration','qq'].includes(String(route.query.tab))?String(route.query.tab):'site')
const form=reactive({siteName:'',siteDescription:'',registrationEnabled:true,registrationMode:'live'})
type Qq={groupId:string;qqNumber:string;name:string;active:boolean;bound:boolean}
const qqs=ref<Qq[]>([]),groups=ref<{groupId:string;count:number}[]>([]),currentGroup=ref(''),search=ref(''),qqStatus=ref(''),qqPage=ref(1),importText=ref('')
const loading=ref(true),error=ref(''),saving=ref(false),qqLoading=ref(false),qqError=ref(''),qqReady=ref(false),rosterFile=ref<File|null>(null),rosterInput=ref<HTMLInputElement|null>(null),replaceRoster=ref(false)
const filtered=computed(()=>qqs.value.filter(q=>q.groupId===currentGroup.value&&`${q.qqNumber} ${q.name}`.toLowerCase().includes(search.value.trim().toLowerCase())&&(!qqStatus.value||(qqStatus.value==='bound'?q.bound:qqStatus.value==='active'?q.active&&!q.bound:!q.active))))
const qqPages=computed(()=>Math.max(1,Math.ceil(filtered.value.length/20)))
const visible=computed(()=>filtered.value.slice((Math.min(qqPage.value,qqPages.value)-1)*20,Math.min(qqPage.value,qqPages.value)*20))
async function load(){loading.value=true;error.value='';try{Object.assign(form,(await api.get('/admin/settings')).data)}catch(e){error.value=message(e)}finally{loading.value=false}}
async function loadQqs(){qqLoading.value=true;qqError.value='';try{const [q,g]=await Promise.all([api.get('/admin/registration/qq-allowlist'),api.get('/admin/registration/qq-groups')]);qqs.value=q.data;groups.value=g.data;if(!groups.value.some(g=>g.groupId===currentGroup.value))currentGroup.value=groups.value[0]?.groupId||'';qqReady.value=true;qqPage.value=1}catch(e){qqError.value=message(e)}finally{qqLoading.value=false}}
function selectTab(next:string){void router.replace({query:next==='site'?{}:{tab:next}});if(next==='qq'&&!qqReady.value)void loadQqs()}
async function save(){if(saving.value)return;saving.value=true;error.value='';try{await api.put('/admin/settings',form);siteName.value=form.siteName;notify(tab.value==='site'?'站点资料已保存':'注册设置已保存')}catch(e){error.value=message(e)}finally{saving.value=false}}
async function importQqs(){if(saving.value)return;saving.value=true;qqError.value='';try{const qqNumbers=importText.value.split(/[\s,，;；]+/).filter(Boolean);const {data}=await api.post('/admin/registration/qq-allowlist',{groupId:currentGroup.value,qqNumbers});importText.value='';notify(`已启用 ${data.count} 个 QQ 号`);await loadQqs()}catch(e){qqError.value=message(e)}finally{saving.value=false}}
function chooseRoster(event:Event){rosterFile.value=(event.target as HTMLInputElement).files?.[0]||null}
async function uploadRoster(){if(!rosterFile.value||saving.value)return;saving.value=true;qqError.value='';try{const formData=new FormData();formData.append('file',rosterFile.value);formData.append('replace',String(replaceRoster.value));const {data}=await api.post('/admin/registration/qq-roster-file',formData);rosterFile.value=null;replaceRoster.value=false;if(rosterInput.value)rosterInput.value.value='';await loadQqs();currentGroup.value=data.groupId;notify(`名单已上传，共 ${data.count} 人`)}catch(e){qqError.value=message(e)}finally{saving.value=false}}
async function toggleQq(q:Qq){if(saving.value)return;saving.value=true;qqError.value='';try{if(q.active)await api.delete(`/admin/registration/qq-allowlist/${encodeURIComponent(q.groupId)}/${q.qqNumber}`);else await api.post('/admin/registration/qq-allowlist',{groupId:q.groupId,qqNumbers:[q.qqNumber]});notify(q.active?'QQ 号已停用':'QQ 号已启用');const previousPage=qqPage.value;await loadQqs();qqPage.value=Math.min(previousPage,qqPages.value)}catch(e){qqError.value=message(e)}finally{saving.value=false}}
onMounted(()=>{void load();if(tab.value==='qq')void loadQqs()})
</script>
<template>
  <header class="admin-page-heading"><div><p class="admin-kicker">SITE SETTINGS</p><h1>站点设置</h1><p>{{isAdmin?'维护网站资料，管理注册方式与准入名单。':'维护网站名称与介绍。'}}</p></div></header>
  <div class="admin-subnav"><button :class="{selected:tab==='site'}" @click="selectTab('site')">站点资料</button><template v-if="isAdmin"><button :class="{selected:tab==='registration'}" @click="selectTab('registration')">注册设置</button><button :class="{selected:tab==='qq'}" @click="selectTab('qq')">QQ 注册名单</button></template></div>
  <p v-if="error" class="error-message" role="alert">{{error}} <button @click="load">重新加载</button></p><p v-if="loading" class="admin-empty">正在加载设置…</p>
  <template v-else-if="!error||form.siteName">
    <div v-if="tab==='site'" class="admin-settings-grid"><form class="admin-surface admin-form" @submit.prevent="save"><div class="admin-section-title"><div><h2>网站基本资料</h2><p>显示在网站导航与公开介绍中。</p></div></div><label>站点名称<input v-model="form.siteName" maxlength="80" required/></label><label>站点介绍<textarea v-model="form.siteDescription" maxlength="300" rows="5" placeholder="用一段话介绍我们的文学社与这片文字天地。"></textarea><small class="admin-character-count">{{form.siteDescription.length}} / 300</small></label><footer class="admin-form-actions"><button class="button" :disabled="saving">{{saving?'保存中…':'保存站点资料'}}</button></footer></form><aside class="admin-help"><Icon name="Settings" :size="24"/><h3>让管理各有归属</h3><p>这里负责网站本身的设置。</p><RouterLink v-if="isAdmin" to="/admin/accounts">账户角色与权限 <Icon name="ArrowRight" :size="14"/></RouterLink><RouterLink v-if="isAdmin" to="/admin/works">文章内容与审核 <Icon name="ArrowRight" :size="14"/></RouterLink></aside></div>
    <div v-else-if="tab==='registration'" class="admin-settings-grid"><form class="admin-surface admin-form" @submit.prevent="save"><div class="admin-section-title"><div><h2>注册方式</h2><p>设置新社员加入网站的方式。</p></div></div><label class="admin-checkbox admin-setting-toggle"><input v-model="form.registrationEnabled" type="checkbox"/><span>开放新用户注册<small>关闭后，已有账户仍可正常登录。</small></span><span class="admin-badge" :class="form.registrationEnabled?'published':'withdrawn'">{{form.registrationEnabled?'已开放':'已关闭'}}</span></label><label>测试账号<select v-model="form.registrationMode"><option value="live">停用测试账号</option><option value="test">启用测试账号（12345 / 0000）</option></select></label><p class="admin-muted">名单中的 QQ 号通过同名 QQ 邮箱接收验证码。测试账号启用时无需发送邮件。</p><footer class="admin-form-actions"><button class="button" :disabled="saving">{{saving?'保存中…':'保存注册设置'}}</button></footer></form><aside class="admin-help"><Icon name="ShieldCheck" :size="24"/><h3>名单准入</h3><p>新社员使用 QQ 号和对应邮箱验证码完成注册。先确认其 QQ 号已纳入群名单。</p><button class="admin-inline-link" @click="selectTab('qq')">管理 QQ 注册名单 <Icon name="ArrowRight" :size="14"/></button></aside></div>
    <template v-else><div class="admin-info"><Icon name="ShieldCheck" :size="20"/><p>每个群对应一个名单文件。相同 QQ 在各群中的启用与绑定状态同步；停用注册资格不会禁用已注册账户。名单文件修改后，请刷新名单。</p></div><p v-if="qqError" class="error-message" role="alert">{{qqError}}</p><form v-if="isSuper" class="admin-surface admin-import-qq admin-form" @submit.prevent="uploadRoster"><h2>上传群名单文件</h2><p class="admin-muted">上传 UTF-8 编码的 .md 文件，文件名作为群名，每行填写 QQ 号、空格和群内名称。勾选替换时，已有同名群名单会被新文件完整替换。</p><label>选择名单文件<input ref="rosterInput" type="file" accept=".md,text/markdown,text/plain" :disabled="saving" @change="chooseRoster"/></label><label class="admin-checkbox"><input v-model="replaceRoster" type="checkbox" :disabled="saving"/>替换同名群名单</label><button class="button small" :disabled="saving||!rosterFile">{{saving?'上传中…':'上传名单'}}</button></form><div class="admin-filters"><label><span class="sr-only">选择 QQ 群</span><select v-model="currentGroup" aria-label="选择 QQ 群" @change="qqPage=1"><option v-for="g in groups" :key="g.groupId" :value="g.groupId">{{g.groupId}}（{{g.count}} 人）</option></select></label><label class="admin-search-field"><Icon name="Search" :size="17"/><input v-model="search" aria-label="搜索 QQ 注册名单" placeholder="搜索 QQ 号或群内名称" @input="qqPage=1"/></label><label><span class="sr-only">QQ 名单状态</span><select v-model="qqStatus" aria-label="QQ 名单状态" @change="qqPage=1"><option value="">全部状态</option><option value="active">可注册</option><option value="bound">已绑定</option><option value="disabled">已停用</option></select></label><button class="button secondary small" :disabled="qqLoading||saving" @click="loadQqs"><Icon name="RefreshCw" :size="15"/>刷新名单</button></div><details v-if="currentGroup" class="admin-surface admin-import-qq"><summary>批量启用当前群的 QQ 号</summary><form class="admin-form" @submit.prevent="importQqs"><label>QQ 号<textarea v-model="importText" rows="3" placeholder="输入已在当前群名单中的 QQ 号，用逗号、空格或换行分隔。" required></textarea></label><button class="button small" :disabled="saving||qqLoading">{{saving?'处理中…':'启用所填 QQ 号'}}</button></form></details><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>QQ 号</th><th>群内名称</th><th>注册资格</th><th>绑定情况</th><th class="admin-cell-end">操作</th></tr></thead><tbody v-if="!qqLoading"><tr v-for="q in visible" :key="q.groupId+q.qqNumber"><td>{{q.qqNumber}}</td><td>{{q.name}}</td><td><span class="admin-badge" :class="q.active?'published':'withdrawn'">{{q.active?'已启用':'已停用'}}</span></td><td>{{q.bound?'已绑定账户':'未绑定'}}</td><td class="admin-cell-end"><button class="admin-inline-link" :disabled="saving" @click="toggleQq(q)">{{q.active?'停用':'启用'}}</button></td></tr></tbody></table><p v-if="qqLoading" class="admin-empty">正在加载注册名单…</p><p v-else-if="!visible.length" class="admin-empty">{{groups.length?'没有匹配的 QQ 号。':'暂无群名单，请由超级管理员上传 Markdown 名单文件。'}}</p></div><div class="admin-table-footer"><p>共 {{filtered.length}} 条记录 · 每页 20 条</p><div class="admin-pagination"><button :disabled="qqPage<=1" aria-label="上一页名单" @click="qqPage--"><Icon name="ChevronLeft" :size="16"/></button><span>{{Math.min(qqPage,qqPages)}} / {{qqPages}}</span><button :disabled="qqPage>=qqPages" aria-label="下一页名单" @click="qqPage++"><Icon name="ChevronRight" :size="16"/></button></div></div></template>
  </template>
</template>
